<!--
  @component
  The equivalent of the HTML `<input type="number">` element.
  @see https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input/number
  @see https://w3c.github.io/aria/#textbox
-->
<script>
  import { _ } from '@sveltia/i18n';
  import { untrack } from 'svelte';
  import Button from '../button/button.svelte';
  import Icon from '../icon/icon.svelte';
  import {
    getMaximumFractionDigits,
    isAtMax,
    isAtMin,
    isInvalidNumber,
    parseNumber,
    stepNumber,
  } from './number-input.js';
  import TextInput from './text-input.svelte';

  /**
   * @import { Snippet } from 'svelte';
   * @import { CommonEventHandlers, InputEventHandlers, TextInputProps } from '../../typedefs.js';
   */

  /**
   * @typedef {object} Props
   * @property {number} [value] Input value.
   * @property {number} [min] Minimum allowed value.
   * @property {number} [max] Maximum allowed value.
   * @property {number} [step] Value to be added or removed when using the up/down arrow key or
   * button.
   * @property {Snippet} [increaseIcon] Increase icon slot content.
   * @property {Snippet} [decreaseIcon] Decrease icon slot content.
   */

  /**
   * @type {TextInputProps & CommonEventHandlers & InputEventHandlers & Props & Record<string, any>}
   */
  let {
    /* eslint-disable prefer-const */
    value = $bindable(),
    invalid = $bindable(false),
    flex = false,
    min = undefined,
    max = undefined,
    step = 1,
    class: className,
    hidden = false,
    disabled = false,
    readonly = false,
    required = false,
    children,
    increaseIcon,
    decreaseIcon,
    onChange,
    onkeydown,
    oninput,
    ...restProps
    /* eslint-enable prefer-const */
  } = $props();

  const id = $props.id();

  let edited = $state(false);
  let inputValue = $state('');

  const maximumFractionDigits = $derived(getMaximumFractionDigits(step));
  const isMin = $derived(isAtMin(inputValue, min));
  const isMax = $derived(isAtMax(inputValue, max));

  $effect(() => {
    const newValue = value;

    // Only overwrite the field when it doesn’t already hold the value, so text that is still being
    // typed, like `1.` or `-`, isn’t wiped out when it parses to the same number or no number
    untrack(() => {
      if (parseNumber(inputValue) !== newValue) {
        inputValue = String(newValue ?? '');
      }
    });
  });

  $effect(() => {
    value = parseNumber(inputValue);
  });

  $effect(() => {
    if (edited) {
      invalid = isInvalidNumber(inputValue, { required, min, max });
    }
  });

  /**
   * Step the number up or down, unless the field holds no number or is already at the limit.
   * @param {1 | -1} direction `1` to increase, `-1` to decrease.
   */
  const stepValue = (direction) => {
    const newInputValue = stepNumber(inputValue, { step, direction, min, max });

    if (newInputValue !== undefined) {
      inputValue = newInputValue;
    }
  };

  /**
   * Decrease the number.
   */
  const decrease = () => {
    stepValue(-1);
  };

  /**
   * Increase the number.
   */
  const increase = () => {
    stepValue(1);
  };
</script>

<div
  role="none"
  class="sui number-input {className}"
  class:flex
  class:disabled
  class:readonly
  {hidden}
>
  <div role="none" class="buttons">
    <Button
      iconic
      disabled={disabled || readonly || Number.isNaN(Number(inputValue)) || isMax}
      aria-label={_('_sui.number_input.increase')}
      aria-controls={id}
      onclick={() => {
        increase();
      }}
    >
      {#snippet startIcon()}
        {#if increaseIcon}
          {@render increaseIcon()}
        {:else}
          <Icon name="expand_less" />
        {/if}
      {/snippet}
    </Button>
    <Button
      iconic
      disabled={disabled || readonly || Number.isNaN(Number(inputValue)) || isMin}
      aria-label={_('_sui.number_input.decrease')}
      aria-controls={id}
      onclick={() => {
        decrease();
      }}
    >
      {#snippet startIcon()}
        {#if decreaseIcon}
          {@render decreaseIcon()}
        {:else}
          <Icon name="expand_more" />
        {/if}
      {/snippet}
    </Button>
  </div>
  <TextInput
    dir="ltr"
    {...restProps}
    role="spinbutton"
    {id}
    bind:value={inputValue}
    spellcheck="false"
    {flex}
    {hidden}
    {disabled}
    {readonly}
    {required}
    {invalid}
    aria-valuenow={Number.isFinite(value) ? value : undefined}
    aria-valuemin={min}
    aria-valuemax={max}
    inputmode={maximumFractionDigits > 0 ? 'decimal' : 'numeric'}
    onkeydown={(event) => {
      const { key, ctrlKey, metaKey, altKey, shiftKey } = event;
      const hasModifier = shiftKey || altKey || ctrlKey || metaKey;
      // A read-only field can’t be stepped, just like the spin buttons
      const canStep = !disabled && !readonly && !hasModifier;

      if (key === 'ArrowDown' && canStep) {
        event.preventDefault();
        decrease();
      }

      if (key === 'ArrowUp' && canStep) {
        event.preventDefault();
        increase();
      }

      if (!edited) {
        edited = true;
      }

      onkeydown?.(event);
    }}
    oninput={(event) => {
      if (!edited) {
        edited = true;
      }

      oninput?.(event);
    }}
    {onChange}
  />
</div>

<style>.number-input {
  display: inline-flex;
  align-items: center;
  margin: var(--sui-focus-ring-width);
  min-width: var(--sui-textbox-singleline-min-width);
}
.number-input.flex:not([hidden]) {
  display: inline-flex;
  width: -moz-available;
  width: -webkit-fill-available;
  width: stretch;
  min-width: 0;
}
.number-input:not(.disabled) :global(button[aria-disabled='true']) {
  filter: grayscale(0) opacity(1);
}
.number-input:not(.disabled) :global(button[aria-disabled='true']) :global(*) {
  filter: grayscale(1) opacity(var(--sui-disabled-opacity, 0.35));
}
.number-input :global(:not(:first-child)) :global(input) {
  border-start-start-radius: 0;
  border-end-start-radius: 0;
}
.number-input :global(:not(:last-child)) :global(input) {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}
.number-input :global(.text-input) {
  flex: auto;
  margin: 0 !important;
  width: 0;
  min-width: 0 !important;
}

.buttons {
  display: flex;
  flex-direction: row;
  width: 48px;
  height: var(--sui-textbox-height);
}
.buttons :global(button) {
  flex: none;
  margin: 0 !important;
  border-width: 1px;
  border-color: var(--sui-textbox-border-color);
  width: 50%;
  height: 100%;
  border-inline-end-width: 0;
}
.buttons :global(button:first-of-type) {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}
.buttons :global(button:last-of-type) {
  border-radius: 0;
}
.buttons :global(button) :global(.icon) {
  font-size: 20px;
}</style>
