<script>
  import { $isCodeNode as isCodeNode } from '@lexical/code-core';
  import { _ } from '@sveltia/i18n';
  import { $getNodeByKey as getNodeByKey, $getRoot as getRoot } from 'lexical';
  import { getContext } from 'svelte';
  import Option from '../../listbox/option.svelte';
  import Select from '../../select/select.svelte';
  import { getBackgroundUpdateTags } from '../background-update.js';
  import { focusEditor, loadCodeHighlighter } from '../core.js';
  import { LANGUAGES } from '../shiki/generated.js';

  /**
   * @import { CodeNode } from '@lexical/code-core';
   * @import { TextEditorStore } from '../../../typedefs.js';
   */

  /**
   * @typedef {object} Props
   * @property {boolean} [disabled] Whether to disable the switcher.
   */

  /** @type {Props} */
  let {
    /* eslint-disable prefer-const */
    disabled = false,
    /* eslint-enable prefer-const */
  } = $props();

  /** @type {{ key: string, label: string, aliases: string[] }[]} */
  const codeLanguages = LANGUAGES.map(({ id, name, aliases = [] }) => ({
    key: id,
    label: name,
    aliases,
  }));

  /** @type {TextEditorStore} */
  const editorStore = getContext('editorStore');

  let selectedLanguage = $state('plain');

  // A code block can carry an alias, e.g. `js`, while the options are keyed by the canonical ID,
  // e.g. `javascript`, so resolve the alias for the selector to find its option. A language that
  // isn’t listed, e.g. `txt`, is shown as plain text; otherwise the selector would keep the label
  // of the previous block, as it only updates the label when an option matches
  const selectedKey = $derived(
    codeLanguages.find(
      ({ key, aliases }) => key === selectedLanguage || aliases.includes(selectedLanguage),
    )?.key ?? 'plain',
  );

  /**
   * Get the code block the switcher targets. A code editor has exactly one code block, and its
   * `blockNodeKey` is still unset the first time the switcher is used, before the editor has ever
   * been focused. Call this within `editor.read()` or `editor.update()`.
   * @returns {CodeNode | null} Code node, or `null` if the selection is not in a code block.
   */
  const getCodeNode = () => {
    const { blockNodeKey } = editorStore.selection;

    const node = editorStore.config.isCodeEditor
      ? getRoot().getChildren()[0]
      : blockNodeKey
        ? getNodeByKey(blockNodeKey)
        : null;

    return isCodeNode(node) ? node : null;
  };

  /**
   * Give the code block the given language, once the highlighter for it has loaded.
   * @param {string} lang Language ID.
   */
  const changeLanguage = async (lang) => {
    const { editor } = editorStore;

    if (!editor || selectedKey === lang) {
      return;
    }

    // The change only reaches the editor, and anything bound to it, once the highlighter has
    // loaded, so report the content as pending until then: the flag the editor sets for itself is
    // cleared by the update the focus move below fires
    const endOperation = editorStore.startOperation();

    try {
      await focusEditor(editor);
      await loadCodeHighlighter(lang);

      // The user may have moved on to another field while the highlighter was loading
      editor.update(
        () => {
          // https://github.com/facebook/lexical/blob/main/packages/lexical-playground/src/plugins/ToolbarPlugin/index.tsx#L713
          const node = getCodeNode();

          if (node) {
            node.setLanguage(lang);
            selectedLanguage = lang;
          }
        },
        { tag: getBackgroundUpdateTags(editor) },
      );
    } finally {
      // The editor has flagged the export that follows as pending by now, so the hand-off leaves
      // no gap
      endOperation();
    }
  };

  $effect(() => {
    void editorStore.selection.blockNodeKey;

    editorStore.editor?.read(() => {
      const node = getCodeNode();

      if (node) {
        // The highlighter gives a block without a language the default one as it’s transformed,
        // so the fallbacks here are only for the unexpected
        /* v8 ignore next */
        selectedLanguage = node.getLanguage() ?? editorStore.config.defaultLanguage ?? 'plain';
      }
    });
  });
</script>

<Select
  {disabled}
  ariaLabel={_('_sui.text_editor.language')}
  value={selectedKey}
  onChange={({ detail: { value: lang } }) => {
    changeLanguage(lang);
  }}
>
  <Option label={_('_sui.text_editor.plain_text')} value="plain" dir="ltr" />
  {#each codeLanguages as { key, label } (key)}
    <Option {label} value={key} selected={key === selectedKey} dir="ltr" />
  {/each}
</Select>
