/* eslint-disable jsdoc/require-jsdoc */

/**
 * Implement a wrapper for the IndexedDB API, making it easier to use the client-side database with
 * auto-upgrades and convenient Promise methods.
 */
export default class IndexedDB {
  /**
   * Database itself.
   * @type {IDBDatabase | undefined}
   */
  #database;

  /**
   * In-flight promise that resolves to the opened database. Used to prevent concurrent callers from
   * opening (and potentially version-bumping) the database in parallel.
   * @type {Promise<IDBDatabase> | undefined}
   */
  #databasePromise;

  /**
   * Database name in use.
   * @type {string}
   */
  #databaseName = '';

  /**
   * Store name in use.
   * @type {string}
   */
  #storeName = '';

  /**
   * Store options to be passed to `IDBDatabase.createObjectStore()`. Note that this cannot be
   * altered after the store is created.
   * @type {IDBObjectStoreParameters}
   */
  #storeOptions = {};

  /**
   * Index options to be passed to `IDBObjectStore.createIndex()`.
   * @type {import("../typedefs").DatabaseIndex[]}
   */
  #indexes = [];

  /**
   * Initialize a new `IndexedDB` instance.
   * @param {string} databaseName Database name.
   * @param {string} storeName Store name.
   * @param {object} [options] Options.
   * @param {string | string[]} [options.keyPath] Option for `createObjectStore()`.
   * @param {boolean} [options.autoIncrement] Option for `createObjectStore()`.
   * @param {import("../typedefs").DatabaseIndex[]} [options.indexes] Arguments for `createIndex()`.
   * @see https://developer.mozilla.org/en-US/docs/Web/API/IDBDatabase/createObjectStore
   * @see https://stackoverflow.com/questions/33852508/how-to-create-an-indexeddb-composite-key
   */
  constructor(databaseName, storeName, { keyPath, autoIncrement, indexes = [] } = {}) {
    this.#database = undefined;
    this.#databaseName = databaseName;
    this.#storeName = storeName;
    this.#storeOptions = { keyPath, autoIncrement };
    this.#indexes = indexes;
  }

  /**
   * Open the database and create a store if needed.
   * @param {number} [version] Database version.
   * @returns {Promise<IDBDatabase>} Database.
   */
  async #openDatabase(version) {
    return new Promise((resolve, reject) => {
      const request = globalThis.indexedDB.open(this.#databaseName, version);

      request.onupgradeneeded = () => {
        const database = request.result;
        const storeName = this.#storeName;

        const store = database.objectStoreNames.contains(storeName)
          ? /** @type {IDBTransaction} */ (request.transaction).objectStore(storeName)
          : database.createObjectStore(storeName, this.#storeOptions);

        this.#indexes.forEach(({ name, keyPath, options }) => {
          if (!store.indexNames.contains(name)) {
            store.createIndex(name, keyPath, options);
          }
        });
      };

      request.onsuccess = () => {
        resolve(request.result);
      };

      request.onerror = () => {
        reject(request.error);
      };
    });
  }

  /**
   * Check whether the database lacks the store or any of the indexes, requiring an upgrade.
   * @param {IDBDatabase} database Database.
   * @returns {boolean} Result.
   */
  #isUpgradeNeeded(database) {
    const storeName = this.#storeName;

    if (!database.objectStoreNames.contains(storeName)) {
      return true;
    }

    const store = database.transaction(storeName).objectStore(storeName);

    return this.#indexes.some(({ name }) => !store.indexNames.contains(name));
  }

  /**
   * Get the database and automatically upgrade it if a new store is not created yet.
   * @returns {Promise<IDBDatabase>} Database.
   */
  async #getDatabase() {
    let database = await this.#openDatabase();

    // Loop because another connection (e.g. another instance using a different store in the same
    // database) may upgrade the database concurrently. In that case our `version + 1` open either
    // succeeds without running `onupgradeneeded`, leaving our store missing, or fails with a
    // `VersionError` because the database is already at a higher version.
    while (this.#isUpgradeNeeded(database)) {
      const { version } = database;

      database.close();

      try {
        // eslint-disable-next-line no-await-in-loop
        database = await this.#openDatabase(version + 1);
      } catch (error) {
        if (/** @type {DOMException} */ (error)?.name !== 'VersionError') {
          throw error;
        }

        // eslint-disable-next-line no-await-in-loop
        database = await this.#openDatabase();
      }
    }

    // Avoid upgrade conflict
    database.onversionchange = () => {
      database.close();
      this.#database = undefined;
    };

    // The connection can also be closed by the browser, e.g. when site data is cleared. Drop the
    // cached reference so the next query reopens the database instead of failing forever.
    database.onclose = () => {
      this.#database = undefined;
    };

    return database;
  }

  /**
   * Create a database if not yet initialized, then execute the given function over the store.
   * @param {(store: IDBObjectStore) => IDBRequest | void} getRequest Function to be executed.
   * @param {object} [options] Options.
   * @param {IDBTransactionMode} [options.mode] Transaction mode. Default: `readonly`.
   * @returns {Promise<any | void>} Result.
   */
  async #query(getRequest, { mode = 'readonly' } = {}) {
    if (!this.#database) {
      // Cache the in-flight promise so concurrent callers share a single DB open.
      this.#databasePromise ??= this.#getDatabase();

      try {
        this.#database = await this.#databasePromise;
      } finally {
        // Clear in `finally`, not after the `await`: if the open fails, the rejected promise must
        // not stay cached, or every later query on this instance would replay the same failure with
        // no way to recover.
        this.#databasePromise = undefined;
      }
    }

    const database = /** @type {IDBDatabase} */ (this.#database);
    const storeName = this.#storeName;
    const transaction = database.transaction(storeName, mode);
    const request = getRequest(transaction.objectStore(storeName));

    return new Promise((resolve, reject) => {
      transaction.onerror = () => {
        reject(transaction.error);
      };

      transaction.onabort = () => {
        reject(transaction.error);
      };

      if (mode === 'readwrite') {
        // For writes, resolve on transaction commit (not on request success) so the caller is only
        // notified once the data is durably persisted.
        /** @type {any} */
        let result;

        if (request) {
          request.onsuccess = () => {
            result = request.result;
          };
        }

        transaction.oncomplete = () => {
          resolve(result);
        };
      } else if (request) {
        request.onsuccess = () => {
          resolve(request.result);
        };
      } else {
        /* v8 ignore next */
        transaction.oncomplete = () => {
          resolve(undefined);
        };
      }
    });
  }

  /**
   * Save a value with an out-of-line key.
   * @param {any} key Key.
   * @param {any} value Value.
   * @returns {Promise<any>} Key.
   */
  async set(key, value) {
    return this.#query((store) => store.put(value, key), { mode: 'readwrite' });
  }

  /**
   * Save a value with an inline key.
   * @param {any} value Value.
   * @returns {Promise<any>} Key.
   */
  async put(value) {
    return this.#query((store) => store.put(value), { mode: 'readwrite' });
  }

  /**
   * Save multiple records.
   * @param {[any, any][]} records Key/value pairs.
   * @returns {Promise<any>} Key.
   */
  async saveEntries(records) {
    return this.#query(
      (store) => {
        records.forEach(([key, value]) => {
          store.put(value, key);
        });
      },
      { mode: 'readwrite' },
    );
  }

  /**
   * Retrieve a value by key.
   * @param {any} key Key.
   * @returns {Promise<any>} Value.
   */
  async get(key) {
    return this.#query((store) => store.get(key));
  }

  /**
   * Retrieve all the keys.
   * @returns {Promise<any[]>} Keys.
   */
  async keys() {
    return this.#query((store) => store.getAllKeys());
  }

  /**
   * Retrieve all the values.
   * @returns {Promise<any[]>} Values.
   */
  async values() {
    return this.#query((store) => store.getAll());
  }

  /**
   * Retrieve all the records.
   * @returns {Promise<[any, any][]>} Key/value pairs.
   */
  async entries() {
    // Bulk-read keys and values rather than walking a cursor, which costs one event-loop round trip
    // per record. Both requests run in the same transaction and return records in key order, so
    // the two arrays line up.
    /** @type {any[]} */
    let keys = [];

    const values = await this.#query((store) => {
      const keysRequest = store.getAllKeys();

      keysRequest.onsuccess = () => {
        keys = keysRequest.result;
      };

      return store.getAll();
    });

    return keys.map((key, index) => [key, values[index]]);
  }

  /**
   * Get the given index of the store, or the store itself if no index is given.
   * @param {IDBObjectStore} store Store.
   * @param {string} [index] Index name.
   * @returns {IDBObjectStore | IDBIndex} Store or index.
   */
  static #getSource(store, index) {
    return index ? store.index(index) : store;
  }

  /**
   * Find a record using a cursor, stopping at the first match.
   * @param {object} args Arguments.
   * @param {(record: any) => boolean} [args.callback] A function to execute for each record.
   * @param {string} [args.index] Index name.
   * @param {IDBValidKey | IDBKeyRange} [args.query] Query option for `openCursor()`.
   * @param {IDBCursorDirection} [args.direction] The direction option for `openCursor()`.
   * @returns {Promise<any>} Found record.
   */
  async #search({
    callback = undefined,
    index = undefined,
    query = undefined,
    direction = 'next',
  }) {
    return new Promise((resolve, reject) => {
      this.#query((store) => {
        const request = IndexedDB.#getSource(store, index).openCursor(query, direction);

        request.onsuccess = () => {
          const cursor = request.result;

          if (cursor) {
            const { value } = cursor;

            if (typeof callback === 'function' ? callback(value) : true) {
              resolve(value);
            } else {
              cursor.continue();
            }
          } else {
            resolve(undefined);
          }
        };
      }).catch(reject);
    });
  }

  /**
   * Find the first record that matches the condition.
   * @param {(record: any) => boolean} [callback] A function to execute for each record.
   * @param {object} [options] Options.
   * @param {string} [options.index] Index.
   * @param {IDBValidKey | IDBKeyRange} [options.query] Query option for `openCursor()`.
   * @returns {Promise<any>} Found record.
   */
  async find(callback, { index, query } = {}) {
    return this.#search({ callback, index, query });
  }

  /**
   * Find the last record that matches the condition.
   * @param {(record: any) => boolean} [callback] A function to execute for each record.
   * @param {object} [options] Options.
   * @param {string} [options.index] Index.
   * @param {IDBValidKey | IDBKeyRange} [options.query] Query option for `openCursor()`.
   * @returns {Promise<any>} Found record.
   */
  async findLast(callback, { index, query } = {}) {
    return this.#search({ callback, index, query, direction: 'prev' });
  }

  /**
   * Find all the records that match the condition.
   * @param {(record: any) => boolean} [callback] A function to execute for each record.
   * @param {object} [options] Options.
   * @param {string} [options.index] Index.
   * @param {IDBValidKey | IDBKeyRange} [options.query] Query option for `openCursor()`.
   * @returns {Promise<any[]>} Found records.
   */
  async filter(callback, { index, query } = {}) {
    // Every record has to be visited anyway, so a single bulk read beats a cursor that costs one
    // event-loop round trip per record. The callback also runs after the transaction is released.
    /** @type {any[]} */
    const values = await this.#query((store) => IndexedDB.#getSource(store, index).getAll(query));

    // Wrap the callback so it only receives the record, not `Array#filter`’s index/array arguments
    return typeof callback === 'function' ? values.filter((value) => callback(value)) : values;
  }

  /**
   * Delete an record by key.
   * @param {any} key Key.
   * @returns {Promise<void>} Result.
   */
  async delete(key) {
    await this.#query((store) => store.delete(key), { mode: 'readwrite' });
  }

  /**
   * Delete multiple records by keys.
   * @param {any[]} keys Property keys.
   * @returns {Promise<void>} Result.
   */
  async deleteEntries(keys) {
    await this.#query(
      (store) => {
        keys.forEach((key) => {
          store.delete(key);
        });
      },
      { mode: 'readwrite' },
    );
  }

  /**
   * Delete all the records.
   * @returns {Promise<void>} Result.
   */
  async clear() {
    await this.#query((store) => store.clear(), { mode: 'readwrite' });
  }
}
